#!/usr/bin/env bash
# The changelog is generated by git-cliff from Conventional Commits.
#   scripts/changelog.sh --check        validate cliff.toml and, when git-cliff
#                                       is installed, render the unreleased notes
#   scripts/changelog.sh --self-test    prove --check refuses a broken config
#   scripts/changelog.sh [args...]      run git-cliff with cliff.toml
# This script does not install git-cliff and does not write a tag.
set -euo pipefail

root="$(git rev-parse --show-toplevel)"
cd "$root"

check_config() {
  python3 - "$1" <<'PY'
import sys
import tomllib

path = sys.argv[1]
try:
    with open(path, "rb") as handle:
        data = tomllib.load(handle)
except FileNotFoundError:
    print(f"{path} is missing", file=sys.stderr)
    sys.exit(1)
except tomllib.TOMLDecodeError as error:
    print(f"{path} is not valid TOML: {error}", file=sys.stderr)
    sys.exit(1)

git = data.get("git") or {}
errors = []
if git.get("conventional_commits") is not True:
    errors.append("git.conventional_commits must be true")
parsers = git.get("commit_parsers") or []
skips = [p for p in parsers if p.get("skip") and "Changelog" in (p.get("footer") or p.get("body") or "")]
if not skips:
    errors.append("no commit parser skips a `Changelog: none` footer")
groups = [str(p.get("group", "")) for p in parsers]
for section in ("Added", "Fixed"):
    if not any(group.endswith(section) for group in groups):
        errors.append(f"no commit parser writes the {section} section")
allowed = {"Added", "Changed", "Deprecated", "Removed", "Fixed", "Security"}
for group in groups:
    name = group.split("-->")[-1]
    if name and name not in allowed:
        errors.append(f"section {name} is not a Keep a Changelog section")
if errors:
    print("\n".join(f"{path}: {error}" for error in errors), file=sys.stderr)
    sys.exit(1)
PY
}

case "${1:-}" in
  --self-test)
    dir="$(mktemp -d)"
    printf '[git]\nconventional_commits = false\n' > "$dir/bad.toml"
    if check_config "$dir/bad.toml" >/dev/null 2>&1; then
      rm -rf "$dir"
      echo "changelog self-test: a broken config was accepted" >&2
      exit 1
    fi
    if check_config "$dir/absent.toml" >/dev/null 2>&1; then
      rm -rf "$dir"
      echo "changelog self-test: a missing config was accepted" >&2
      exit 1
    fi
    rm -rf "$dir"
    check_config cliff.toml
    echo "changelog self-test ok"
    ;;
  --check)
    check_config cliff.toml
    if command -v git-cliff >/dev/null 2>&1; then
      git-cliff --config cliff.toml --unreleased >/dev/null
      echo "changelog ok (git-cliff rendered the unreleased notes)"
    else
      echo "changelog config ok (git-cliff is not installed; notes were not rendered)"
    fi
    ;;
  *)
    if ! command -v git-cliff >/dev/null 2>&1; then
      echo "git-cliff is not installed" >&2
      exit 1
    fi
    exec git-cliff --config cliff.toml "$@"
    ;;
esac
